import { Result } from '../shared/Result';

export interface RepairQuote {
  id: string;
  customerId: string;
  status: 'sent' | 'accepted' | 'declined';
  totalCents: number;
  issuedAt: Date;
}

export interface QuoteRepository {
  get(id: string): Promise<RepairQuote | null>;
  save(quote: RepairQuote): Promise<void>;
}

export interface TechnicianScheduler {
  book(quoteId: string, depositCents: number): Promise<string>;
}

export type AcceptError =
  | { kind: 'QuoteNotFound' }
  | { kind: 'NotYourQuote' }
  | { kind: 'NotPending'; status: RepairQuote['status'] }
  | { kind: 'QuoteExpired' };

const VALID_MS = 14 * 86_400_000;
const DEPOSIT_RATE = 0.2;

export class AcceptRepairQuote {
  constructor(
    private readonly quotes: QuoteRepository,
    private readonly scheduler: TechnicianScheduler,
    private readonly now: () => Date,
  ) {}

  async execute(quoteId: string, customerId: string): Promise<Result<{ visitId: string; depositCents: number }, AcceptError>> {
    const quote = await this.quotes.get(quoteId);
    if (!quote) return Result.fail({ kind: 'QuoteNotFound' });
    if (quote.customerId !== customerId) return Result.fail({ kind: 'NotYourQuote' });
    if (quote.status !== 'sent') return Result.fail({ kind: 'NotPending', status: quote.status });
    if (this.now().getTime() - quote.issuedAt.getTime() > VALID_MS) return Result.fail({ kind: 'QuoteExpired' });
    const depositCents = Math.round(quote.totalCents * DEPOSIT_RATE);
    const visitId = await this.scheduler.book(quote.id, depositCents);
    await this.quotes.save({ ...quote, status: 'accepted' });
    return Result.ok({ visitId, depositCents });
  }
}
