Standings are derived data: instead of updating counters incrementally (and risking drift), the domain recomputes the table from all recorded results. For a league season that is a few hundred matches at most, so it is cheap.

### Domain (`src/domain/league.ts`)
```typescript
import { Result } from '../shared/Result';

export type Outcome =
  | { kind: 'Score'; homeGoals: number; awayGoals: number }
  | { kind: 'Forfeit'; forfeitingTeamId: string };

export interface PlayedMatch {
  readonly homeId: string;
  readonly awayId: string;
  readonly homeGoals: number;
  readonly awayGoals: number;
}

export interface StandingRow {
  readonly teamId: string;
  readonly name: string;
  played: number;
  won: number;
  drawn: number;
  lost: number;
  goalsFor: number;
  goalsAgainst: number;
  points: number;
}

export type MatchError =
  | { kind: 'MatchNotFound' }
  | { kind: 'AlreadyRecorded' }
  | { kind: 'InvalidScore' }
  | { kind: 'ForfeitByOutsider'; teamId: string };

export const FORFEIT_GOALS = 3;

export class ScheduledMatch {
  constructor(
    readonly id: string,
    readonly leagueId: string,
    readonly homeId: string,
    readonly awayId: string,
    private result: PlayedMatch | null,
  ) {}

  get played(): PlayedMatch | null { return this.result; }

  record(outcome: Outcome): Result<PlayedMatch, MatchError> {
    if (this.result) return Result.fail({ kind: 'AlreadyRecorded' });
    let homeGoals: number;
    let awayGoals: number;
    if (outcome.kind === 'Forfeit') {
      if (outcome.forfeitingTeamId !== this.homeId && outcome.forfeitingTeamId !== this.awayId) {
        return Result.fail({ kind: 'ForfeitByOutsider', teamId: outcome.forfeitingTeamId });
      }
      const homeForfeits = outcome.forfeitingTeamId === this.homeId;
      homeGoals = homeForfeits ? 0 : FORFEIT_GOALS;
      awayGoals = homeForfeits ? FORFEIT_GOALS : 0;
    } else {
      const valid = (g: number) => Number.isInteger(g) && g >= 0;
      if (!valid(outcome.homeGoals) || !valid(outcome.awayGoals)) return Result.fail({ kind: 'InvalidScore' });
      homeGoals = outcome.homeGoals;
      awayGoals = outcome.awayGoals;
    }
    this.result = { homeId: this.homeId, awayId: this.awayId, homeGoals, awayGoals };
    return Result.ok(this.result);
  }
}

function apply(row: StandingRow, scored: number, conceded: number): void {
  row.played += 1;
  row.goalsFor += scored;
  row.goalsAgainst += conceded;
  if (scored > conceded) { row.won += 1; row.points += 3; }
  else if (scored === conceded) { row.drawn += 1; row.points += 1; }
  else { row.lost += 1; }
}

export function computeStandings(teams: ReadonlyMap<string, string>, matches: readonly PlayedMatch[]): StandingRow[] {
  const rows = new Map<string, StandingRow>();
  for (const [teamId, name] of teams) {
    rows.set(teamId, { teamId, name, played: 0, won: 0, drawn: 0, lost: 0, goalsFor: 0, goalsAgainst: 0, points: 0 });
  }
  for (const m of matches) {
    const home = rows.get(m.homeId);
    const away = rows.get(m.awayId);
    if (home) apply(home, m.homeGoals, m.awayGoals);
    if (away) apply(away, m.awayGoals, m.homeGoals);
  }
  const diff = (r: StandingRow) => r.goalsFor - r.goalsAgainst;
  return [...rows.values()].sort(
    (a, b) => b.points - a.points || diff(b) - diff(a) || b.goalsFor - a.goalsFor || a.name.localeCompare(b.name),
  );
}
```

### Application (`src/application/RecordMatchResult.ts`)
```typescript
import { Result } from '../shared/Result';
import { MatchError, Outcome, PlayedMatch, ScheduledMatch, StandingRow, computeStandings } from '../domain/league';

export interface MatchRepository {
  findInLeague(leagueId: string, matchId: string): Promise<ScheduledMatch | null>;
  save(match: ScheduledMatch): Promise<void>;
  playedInLeague(leagueId: string): Promise<readonly PlayedMatch[]>;
}

export interface TeamDirectory {
  namesInLeague(leagueId: string): Promise<ReadonlyMap<string, string>>;
}

export class RecordMatchResult {
  constructor(private readonly matches: MatchRepository, private readonly teams: TeamDirectory) {}

  async execute(leagueId: string, matchId: string, outcome: Outcome): Promise<Result<StandingRow[], MatchError>> {
    const match = await this.matches.findInLeague(leagueId, matchId);
    if (!match) return Result.fail({ kind: 'MatchNotFound' });

    const recorded = match.record(outcome);
    if (!recorded.success) return recorded;
    await this.matches.save(match);

    const [names, played] = await Promise.all([this.teams.namesInLeague(leagueId), this.matches.playedInLeague(leagueId)]);
    return Result.ok(computeStandings(names, played));
  }
}
```
Looking the match up by league and id together covers "the match must belong to the league" without a separate check. Two teams level on 10 points with goal difference +4 are separated by goals scored, and only then by name.

The tariff and the consumption rules are pure arithmetic over the account and the reading, so they live in the domain with integer cents and whole kWh. The use case loads the account, saves the bill and the advanced account together.

#### 1. Domain (`src/domain/billing.ts`)
```typescript
import { Result } from '../shared/Result';

export interface MeterAccount {
  readonly accountId: string;
  readonly lastReadingKwh: number;
  readonly lastReadOn: Date;
}

export interface NewReading {
  readonly valueKwh: number;
  readonly readOn: Date;
  readonly replacedMeterFinalKwh?: number;
}

export interface Bill {
  readonly accountId: string;
  readonly from: Date;
  readonly to: Date;
  readonly days: number;
  readonly consumptionKwh: number;
  readonly energyCents: number;
  readonly serviceCents: number;
  readonly totalCents: number;
}

export type BillingError =
  | { kind: 'AccountNotFound' }
  | { kind: 'InvalidPeriod'; days: number }
  | { kind: 'NegativeConsumption' };

const DAY_MS = 86_400_000;
export const MIN_DAYS = 27;
export const MAX_DAYS = 33;
const TIERS: readonly { upToKwh: number; cents: number }[] = [
  { upToKwh: 100, cents: 12 },
  { upToKwh: 500, cents: 15 },
  { upToKwh: Infinity, cents: 20 },
];
export const SERVICE_CENTS_PER_DAY = 30;

export function consumption(account: MeterAccount, reading: NewReading): number {
  return reading.replacedMeterFinalKwh === undefined
    ? reading.valueKwh - account.lastReadingKwh
    : reading.replacedMeterFinalKwh - account.lastReadingKwh + reading.valueKwh;
}

export function energyCharge(kwh: number, days: number): number {
  let cents = 0;
  let lower = 0;
  for (const tier of TIERS) {
    const upper = tier.upToKwh === Infinity ? Infinity : Math.round((tier.upToKwh * days) / 30);
    const inTier = Math.max(0, Math.min(kwh, upper) - lower);
    cents += inTier * tier.cents;
    lower = upper;
  }
  return cents;
}

export function closePeriod(account: MeterAccount, reading: NewReading): Result<Bill, BillingError> {
  const days = Math.round((reading.readOn.getTime() - account.lastReadOn.getTime()) / DAY_MS);
  if (days < MIN_DAYS || days > MAX_DAYS) return Result.fail({ kind: 'InvalidPeriod', days });

  const kwh = consumption(account, reading);
  if (kwh < 0) return Result.fail({ kind: 'NegativeConsumption' });

  const energyCents = energyCharge(kwh, days);
  const serviceCents = days * SERVICE_CENTS_PER_DAY;
  return Result.ok({
    accountId: account.accountId,
    from: account.lastReadOn,
    to: reading.readOn,
    days,
    consumptionKwh: kwh,
    energyCents,
    serviceCents,
    totalCents: energyCents + serviceCents,
  });
}
```

#### 2. Application (`src/application/CloseBillingPeriod.ts`)
```typescript
import { Result } from '../shared/Result';
import { Bill, BillingError, MeterAccount, NewReading, closePeriod } from '../domain/billing';

export interface MeterAccountRepository {
  findById(accountId: string): Promise<MeterAccount | null>;
}

export interface BillingStore {
  // Saves the bill and the advanced account atomically.
  commit(bill: Bill, account: MeterAccount): Promise<void>;
}

export class CloseBillingPeriod {
  constructor(private readonly accounts: MeterAccountRepository, private readonly store: BillingStore) {}

  async execute(accountId: string, reading: NewReading): Promise<Result<Bill, BillingError>> {
    const account = await this.accounts.findById(accountId);
    if (!account) return Result.fail({ kind: 'AccountNotFound' });

    const bill = closePeriod(account, reading);
    if (!bill.success) return bill;

    await this.store.commit(bill.data, { accountId, lastReadingKwh: reading.valueKwh, lastReadOn: reading.readOn });
    return bill;
  }
}
```

Worked example: 31 days and 650 kWh scale the limits to 103 and 517 kWh, so energy is 103 × 12 + 414 × 15 + 133 × 20 = 10,106 cents, service is 930 cents, total 110.36. After a meter swap the stored last reading becomes the new meter's value, not the old final reading. `BillingStore.commit` is one database transaction in infrastructure, so a crash cannot leave a bill without the account moving forward (or the reverse).
